CREATE TABLE breeding (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, female_animal_id BIGINT UNSIGNED NOT NULL, male_animal_id BIGINT UNSIGNED NULL, breeding_date DATE NOT NULL, expected_birth_date DATE NULL, actual_birth_date DATE NULL, offspring_count SMALLINT UNSIGNED NULL, status ENUM('planned','confirmed','successful','unsuccessful','cancelled') NOT NULL DEFAULT 'planned', notes TEXT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, KEY idx_breeding_female_date (female_animal_id,breeding_date), CONSTRAINT chk_breeding_count CHECK (offspring_count IS NULL OR offspring_count >= 0), CONSTRAINT chk_breeding_animals CHECK (male_animal_id IS NULL OR female_animal_id <> male_animal_id), CONSTRAINT chk_breeding_expected_date CHECK (expected_birth_date IS NULL OR expected_birth_date >= breeding_date), CONSTRAINT chk_breeding_actual_date CHECK (actual_birth_date IS NULL OR actual_birth_date >= breeding_date), CONSTRAINT fk_breeding_female FOREIGN KEY (female_animal_id) REFERENCES animals(id) ON DELETE RESTRICT, CONSTRAINT fk_breeding_male FOREIGN KEY (male_animal_id) REFERENCES animals(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
